    text: "Final owner review MUST also show what happens to held data after the grant ends, as [Held data after a grant ends](#held-data) defines: [...] for a grant without a processing permission, that the client may keep using the data it received for the approved purpose, unless the owner asks for deletion; [...] for a grant that carries a processing permission, that the client may keep that data but has no ordinary surviving use of it. Continued processing is limited to already-issued processing authority within the defining profile's cessation bound and any earlier applicable deadline; [...] the retention limit, or, when the grant has no `retention`, that there is no stated limit and the client may keep the data until it receives a deletion request; [...] that the owner can ask for deletion at any time while the client may hold the data; [...] that the client learns of a deletion request made at the AS only when it next obtains an answer from the AS. The client attempts one at least once a day while it runs, retrying hourly after a failed attempt and at least daily during a long outage ([Positive assessment and reconciliation](#reconciliation)); [...] that an attempt is not an answer, and that there is no maximum delivery delay; [...] that a client that is not running does not check, and learns of a deletion request only when it next runs and checks; [...] that, if the AS stops answering for good, the client of a grant without a processing permission may keep and use the data for the approved purpose indefinitely when the grant states no retention limit; [...] that, for a grant that carries a processing permission, the AS's silence lets the client keep the data but never extends processing authority or permits ordinary use; [...] that a deletion covers all data the client received under the grant, its derivatives, and copies held by processors and in backups, subject to the exclusions and legal-retention exception in [Erasure](#erasure); [...] that the client's stated retention limit, if any, bounds this, and that the owner can decline a grant that states none; [...] that, if the client offers deletion, choosing it inside the client binds the client at once as an instruction, but is not instant physical deletion.",
